package com.rpsbattle.tournament;
import com.rpsbattle.tournament.domain.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import static org.assertj.core.api.Assertions.*;

class OrganizerMetricsApiTest extends StageThreeWebFixture {
 @Autowired JdbcTemplate db;
 String cup()throws Exception{loginAccount();var t=request("/api/tournaments","POST",Map.of("name","Metrics scope","format","SINGLE_ELIMINATION","maxParticipants",64,"botPolicy",Map.of("submissionMode","BOTH")),201);String base="/api/tournaments/"+t.path("id").asText();request(base+"/timeline","PUT",Map.of("revision",t.path("revision").asLong(),"timeline",TournamentTimelineTest.timeline()),200);return base;}
 UUID tid(String base){return UUID.fromString(base.substring(base.lastIndexOf('/')+1));}
 UUID person(){UUID id=UUID.randomUUID();String name="metric_"+id.toString().substring(0,8);db.update("insert into users(id,username,email,password_hash,display_name) values(?,?,?,?,?)",id,name,name+"@example.invalid","unused fixture hash",name);return id;}
 void application(UUID t,UUID u,String status){db.update("insert into tournament_timeline_registrations(id,tournament_id,user_id,display_name,intended_language,status,registered_at,rules_accepted_at) values(?,?,?,'Metrics person','PYTHON',?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",UUID.randomUUID(),t,u,status);}
 UUID version(UUID t,UUID u,String language,String status){var ids=db.queryForList("select id from tournament_code_workspaces where tournament_id=? and user_id=? and language=?",UUID.class,t,u,language);UUID w=ids.isEmpty()?UUID.randomUUID():ids.getFirst();if(ids.isEmpty())db.update("insert into tournament_code_workspaces(id,tournament_id,user_id,language,source_code,status,created_at,updated_at) values(?,?,?,?,'PRIVATE_SOURCE','DRAFT',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",w,t,u,language);UUID v=UUID.randomUUID();int number=db.queryForObject("select count(*) from tournament_submission_versions where workspace_id=?",Integer.class,w)+1;db.update("insert into tournament_submission_versions(id,workspace_id,version_number,source_code,source_hash,artifact_hash,status,build_log,created_at,updated_at) values(?,?,?,'PRIVATE_SOURCE',?,?,?,'PRIVATE_LOG',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",v,w,number,"a".repeat(64),"b".repeat(64),status);db.update("update tournament_code_workspaces set current_version_id=?,status=? where id=?",v,status,w);return v;}
 void validation(UUID t,UUID u,int cutoff,String status,boolean applied,boolean emergency,String history){UUID v=version(t,u,"PYTHON","LOCKED"),freeze=UUID.randomUUID(),f=UUID.randomUUID();db.update("insert into tournament_coding_freezes(id,tournament_id,user_id,coding_close_at,decision,version_id,version_number,language,source_hash,artifact_hash,submitted_at,frozen_at) values(?,?,?,?,'EXPLICIT_SUBMIT',?,1,'PYTHON',?,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",freeze,t,u,java.sql.Timestamp.from(TournamentTimelineTest.START.plusSeconds(cutoff)),v,"a".repeat(64),"b".repeat(64));db.update("insert into tournament_final_validations(id,freeze_id,tournament_id,user_id,version_id,artifact_hash,source_hash,status,failure_policy,steps_json,history_json,created_at,applied_at) values(?,?,?,?,?,?,?,?,'DISQUALIFY','{}',?,CURRENT_TIMESTAMP,?)",f,freeze,t,u,v,"b".repeat(64),"a".repeat(64),status,history,applied?java.sql.Timestamp.from(Instant.now()):null);if(emergency)db.update("update tournament_final_validations set emergency_open_at=?,emergency_deadline=?,emergency_actor=?,emergency_reason='Fixture' where id=?",java.sql.Timestamp.from(Instant.now().minusSeconds(1)),java.sql.Timestamp.from(Instant.now().plusSeconds(600)),account.id().value(),f);}
 @Test void registrationTotalsAreNotLimitedToOnePageAndOtherAccountsCannotReadThem()throws Exception{
  String base=cup();UUID t=tid(base);for(int i=0;i<34;i++)application(t,person(),i<27?"PENDING":i<30?"APPROVED":i<32?"WAITLISTED":i==32?"REJECTED":"CANCELLED");String other=cup();application(tid(other),person(),"APPROVED");
  var data=request(base+"/organizer-metrics","GET",null,200);assertThat(data.path("registration").path("registered").asInt()).isEqualTo(34);assertThat(data.path("registration").path("pending").asInt()).isEqualTo(27);assertThat(data.path("registration").path("approved").asInt()).isEqualTo(3);assertThat(request(base+"/participant-applications","GET",null,200).path("items").size()).isEqualTo(25);assertThat(data.toString()).doesNotContain("PRIVATE_SOURCE","PRIVATE_LOG","credential","registrationToken","sourceCode","hiddenResult");
  var response=accountHttp.send(java.net.http.HttpRequest.newBuilder(java.net.URI.create("http://localhost:"+port+base+"/organizer-metrics")).GET().build(),java.net.http.HttpResponse.BodyHandlers.ofString());assertThat(response.headers().firstValue("Cache-Control").orElse("")).contains("no-store");assertThat(response.headers().allValues("Vary").toString()).contains("Cookie");
  request("/api/auth/logout","POST",Map.of(),200);request(base+"/organizer-metrics","GET",null,401);account=null;loginAccount();request(base+"/organizer-metrics","GET",null,403);
 }
 @Test void codingDeduplicatesLanguagesIgnoresUnapprovedAndUsesCurrentVersions()throws Exception{
  String base=cup();UUID t=tid(base),a=person(),b=person(),c=person(),stranger=person();for(UUID u:List.of(a,b,c))application(t,u,"APPROVED");application(t,stranger,"REJECTED");version(t,a,"PYTHON","READY");version(t,a,"CPP","BUILD_FAILED");version(t,b,"PYTHON","BUILD_FAILED");version(t,stranger,"PYTHON","READY");
  var coding=request(base+"/organizer-metrics","GET",null,200).path("coding");assertThat(coding.path("approved").asInt()).isEqualTo(3);assertThat(coding.path("workspaceUsers").asInt()).isEqualTo(2);assertThat(coding.path("ready").asInt()).isEqualTo(1);assertThat(coding.path("buildFailed").asInt()).isEqualTo(1);assertThat(coding.path("notStarted").asInt()).isEqualTo(1);assertThat(coding.path("submitted").asInt()).isZero();
 }
 @Test void validationCountsLatestFreezeExcludesExtendedAndRequiresAppliedPassForCheckIn()throws Exception{
  String base=cup();UUID t=tid(base),a=person(),b=person(),c=person(),d=person();for(UUID u:List.of(a,b,c,d))application(t,u,"APPROVED");validation(t,a,100,"PASSED",true,false,"[]");validation(t,a,200,"INFRA_ERROR",false,false,"[]");validation(t,b,200,"FAILED",true,true,"[]");validation(t,c,200,"PASSED",true,false,"[]");validation(t,d,200,"PASSED",true,false,"[{\"status\":\"TIMELINE_EXTENDED\"}]");
  var tournament=tournaments.find(t.toString());tournament.registrations.add(new TournamentRegistration(UUID.randomUUID(),t,c,null,null,"Eligible",TournamentRegistration.Status.APPROVED,Instant.now(),Instant.now(),null));tournament.registrations.add(new TournamentRegistration(UUID.randomUUID(),t,a,null,null,"Infra",TournamentRegistration.Status.APPROVED,Instant.now(),Instant.now(),null));
  var data=request(base+"/organizer-metrics","GET",null,200);assertThat(data.path("validation").path("total").asInt()).isEqualTo(3);assertThat(data.path("validation").path("passed").asInt()).isEqualTo(1);assertThat(data.path("validation").path("infraError").asInt()).isEqualTo(1);assertThat(data.path("validation").path("emergencyOpen").asInt()).isEqualTo(1);assertThat(data.path("checkIn").path("eligible").asInt()).isEqualTo(1);assertThat(data.path("checkIn").path("missing").asInt()).isEqualTo(1);
 }
 @Test void validationFilterRunsBeforePaginationAndDoesNotExposeOtherTournaments()throws Exception{
  String base=cup();UUID t=tid(base);validation(t,person(),100,"INFRA_ERROR",false,false,"[]");for(int i=0;i<27;i++)validation(t,person(),100,"FAILED",true,false,"[]");
  var filtered=request(base+"/final-validations?status=INFRA_ERROR","GET",null,200).path("items");assertThat(filtered.size()).isEqualTo(1);assertThat(filtered.get(0).path("status").asText()).isEqualTo("INFRA_ERROR");assertThat(request(base+"/final-validations?status=FAILED&page=1","GET",null,200).path("items").size()).isEqualTo(2);request(base+"/final-validations?status=HACK","GET",null,400);String other=cup();assertThat(request(other+"/final-validations?status=FAILED","GET",null,200).path("items").size()).isZero();
 }
 @Test void workerSummaryDoesNotCountGlobalMachinesAndCapacityIsNotInvented()throws Exception{
  String base=cup();db.update("insert into workers(id,name,worker_version,protocol_version,status,approval_status,trust_level,registered_at,last_heartbeat_at) values(?,'OTHER_PRIVATE_MACHINE','test',1,'ONLINE','APPROVED','TRUSTED',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",UUID.randomUUID());var data=request(base+"/organizer-metrics","GET",null,200);assertThat(data.path("workers").path("serving").asInt()).isZero();assertThat(data.path("workers").path("availableSlots").isNull()).isTrue();assertThat(data.toString()).doesNotContain("OTHER_PRIVATE_MACHINE");
 }
 @Test void projectionKeepsSubmittedSeparateFromReadyAndOnlyAppliedPassQualifies(){
  UUID a=UUID.randomUUID(),b=UUID.randomUUID(),c=UUID.randomUUID(),tid=UUID.randomUUID();var t=new Tournament(tid.toString(),"Projection",TournamentFormat.SINGLE_ELIMINATION,TournamentTimelineTest.START);t.timeline=TournamentTimelineTest.timeline();t.status=TournamentStatus.REGISTRATION;
  for(UUID u:List.of(a,b,c))t.registrations.add(new TournamentRegistration(UUID.randomUUID(),tid,u,null,null,"Fixture",TournamentRegistration.Status.APPROVED,Instant.now(),Instant.now(),null));
  var snapshot=new OrganizerMetricsStore.Snapshot(Map.of(a,"APPROVED",b,"APPROVED",c,"APPROVED"),List.of(new OrganizerMetricsStore.Workspace(a,"READY","READY"),new OrganizerMetricsStore.Workspace(b,"BUILD_FAILED","BUILD_FAILED")),Map.of(a,"LOCKED",b,"SUBMITTED",c,"REJECTED"),List.of(new OrganizerMetricsStore.Validation(a,"PASSED",false,null),new OrganizerMetricsStore.Validation(b,"PASSED",true,null)),new OrganizerMetricsStore.Workers(0,0,0,0,0,null,"Unknown"));
  var view=OrganizerMetricsService.project(t,snapshot,TournamentTimelineTest.START.plusSeconds(300));assertThat(view.coding().submitted()).isEqualTo(2);assertThat(view.coding().ready()).isEqualTo(1);assertThat(view.checkIn().eligible()).isEqualTo(1);assertThat(view.checkIn().missing()).isEqualTo(1);assertThat(view.checkIn().missed()).isEqualTo(1);
 }
 @Test void runningRetryCountsAreASubsetRatherThanAddingFakeMatches(){
  var t=new Tournament(UUID.randomUUID().toString(),"Running",TournamentFormat.ROUND_ROBIN,Instant.now());t.status=TournamentStatus.RUNNING;var a=new TournamentParticipant("a",null,null,"A",1);var b=new TournamentParticipant("b",null,null,"B",2);int index=0;for(var state:List.of(TournamentMatch.Status.FINISHED,TournamentMatch.Status.RUNNING,TournamentMatch.Status.PENDING,TournamentMatch.Status.PENDING,TournamentMatch.Status.FAILED)){var m=new TournamentMatch("m"+index++,t.id,a,b);m.status=state;m.attempt=index==2||index==4?2:1;t.matches.add(m);}var snapshot=new OrganizerMetricsStore.Snapshot(Map.of(),List.of(),Map.of(),List.of(),new OrganizerMetricsStore.Workers(0,0,0,0,0,null,"Unknown"));var r=OrganizerMetricsService.project(t,snapshot,Instant.now()).running();assertThat(r.total()).isEqualTo(5);assertThat(r.completed()+r.running()+r.queued()+r.error()).isEqualTo(r.total());assertThat(r.retrying()).isEqualTo(2);
 }
}
